export function cameraConstraints({facing='user',deviceId=''}={}){return {audio:false,video:{...(deviceId?{deviceId:{exact:deviceId}}:{facingMode:{ideal:facing}}),width:{ideal:1280},height:{ideal:960},frameRate:{ideal:15,max:30}}}}
export function cameraInfo(track){let caps={},settings={};try{caps=track?.getCapabilities?.()||{}}catch{}try{settings=track?.getSettings?.()||{}}catch{}const z=caps.zoom,supported=Number.isFinite(z?.min)&&Number.isFinite(z?.max)&&z.max>z.min&&z.min>0;return {deviceId:settings.deviceId||'',facing:settings.facingMode,zoom:supported?{min:z.min,max:Math.max(z.min,Math.min(z.max,4)),step:z.step>0?z.step:.1,value:Number.isFinite(settings.zoom)?settings.zoom:z.min}:null}}
export async function setCameraZoom(track,value){const info=cameraInfo(track);if(!info.zoom)throw Error('Camera zoom is unavailable');const z=info.zoom,target=Math.max(z.min,Math.min(z.max,Number(value)));if(!Number.isFinite(target))throw Error('Invalid zoom');await track.applyConstraints({advanced:[{zoom:target}]});const actual=cameraInfo(track).zoom?.value;if(!Number.isFinite(actual)||Math.abs(actual-target)>Math.max(z.step,.05))throw Error('Camera did not apply the requested zoom');return actual}
